// Generate WARNING Bookmarks at instructions whose pcode contains a CALLOTHER op.
// This is useful to find PseudoOps that need to be implemented to yield better
// emulation or decompilation.
// @category Sleigh

using ghidra.app.script;
using ghidra.program.disassemble;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.program.model.pcode;

public class MarkCallOtherPcode : GhidraScript {

	/* @Override */
	public void run()
    {
		if (currentProgram == null) {
			return;
		}
		AddressSetView set = currentSelection;
		if (set == null || set.isEmpty()) {
			set = currentProgram.getMemory().getExecuteSet();
		}

		Disassembler.clearUnimplementedPcodeWarnings(currentProgram, set, monitor);

		int completed = 0;
		monitor.initialize(set.getNumAddresses());

		InstructionIterator instructions = currentProgram.getListing().getInstructions(set, true);
		while (instructions.hasNext()) {
			monitor.checkCancelled();
			Instruction instr = instructions.next();

			PcodeOp[] pcode = instr.getPcode();

			for (int i = 0; i < pcode.length; i++) {
				if (pcode[i].getOpcode() == PcodeOp.CALLOTHER) {
					markCallOtherPcode(instr, pcode[i]);
				}
			}

			completed += instr.getLength();
			if ((completed % 1000) == 0) {
				monitor.setProgress(completed);
			}
		}

	}

	private void markCallOtherPcode(Instruction instr, PcodeOp op) {
		currentProgram.getBookmarkManager()
				.setBookmark(instr.getAddress(), BookmarkType.WARNING, "CallOther PcodeOp",
					currentProgram.getLanguage()
							.getUserDefinedOpName((int) op.getInput(0).getOffset()));
	}
}
